contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable {
        require(amount > 0);

        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;
        uint amountSent = amount <= cBalBefore ? amount : cBalBefore;

        bool reverted;
        c.sendMoney(address(this), amountSent, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalAfter = address(c).balance;
        uint countAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(!reverted
            && cBalAfter == cBalBefore - amountSent
            && countAfter == countBefore);
    }
}

