        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.assume(amount > 0);
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        uint amountSent = amount <= cBalBefore ? amount : cBalBefore;
        bool reverted;
        try c.sendMoney(address(this), amountSent, "") {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint cBalAfter = address(c).balance;
        uint256 countAfter;
        try c.depositsCount() returns (uint256 __r) { countAfter = __r; } catch { return; }
